INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('aa000000-0000-0000-0000-0000000002d1',1,'APPROVED','PUBLISHED',
'{"objectives":["Discuss language policy and standardisation at B2","Use Sprachpolitik und Normierung vocabulary","Talk about German standard language, spelling reform, and language politics"],"explanation":{"intro":"Language policy and standardisation vocabulary covers German language regulation, spelling reform, and institutional language governance at B2.","culturalNote":"Sprachpolitik und Normierung: Standard German (Hochdeutsch — Standarddeutsch) — historically based on Central German chancellery language, codified by Konrad Duden (1880). Key body: Rat für deutsche Rechtschreibung (Council for German Spelling — since 2004). Rechtschreibreform (German spelling reform — 1996 — highly controversial — Neue Regelung). Goethe-Institut (German cultural diplomacy — language teaching worldwide). Sprachpolitik (language policy) in EU: German one of 24 official EU languages. Deutsch als Fremdsprache (DaF). Key debates: Anglizismen (anglicisms — proliferation of English loans — e.g. shoppen, Computer, joggen), German vocabulary loss, Sprachpflege (language cultivation — Verein Deutsche Sprache). Bundesdeutsch vs. Österreichisches Deutsch vs. Schweizer Hochdeutsch."},"examples":[{"german":"Sprachnormierung ist keine objektive Beschreibung, sondern ein politischer Akt: Die Entscheidung, welche Varietät als Standard gilt, begünstigt die Sprecher dieser Varietät und marginalisiert andere — was als ''korrektes'' Deutsch gilt, ist das Ergebnis sozialer Machtverhältnisse, nicht linguistischer Überlegenheit.","english":"Language standardisation is not an objective description, but a political act: the decision of which variety counts as the standard favours speakers of that variety and marginalises others — what counts as ''correct'' German is the result of social power relations, not linguistic superiority."},{"german":"Die Rechtschreibreform von 1996 illustriert, wie sprachpolitische Entscheidungen gesellschaftlichen Widerstand provozieren können: Was linguistisch als pragmatische Vereinfachung intendiert war, wurde von Teilen der Öffentlichkeit als Angriff auf kulturelle Tradition empfunden — ein Beleg dafür, dass Sprache nicht nur Kommunikationsmittel, sondern Identitätsträger ist.","english":"The 1996 spelling reform illustrates how language policy decisions can provoke social resistance: what was linguistically intended as a pragmatic simplification was perceived by parts of the public as an attack on cultural tradition — evidence that language is not only a means of communication, but a carrier of identity."}],"rewards":{"xp":150,"coins":80},"metadata":{"estimatedMinutes":20,"canDo":"I can discuss German spelling reform, language standardisation as power, and Sprachpflege at B2."}}',
'{"items":[{"word":"die Normierung","translation":"standardisation","pronunciation":"dee NOR-mee-roong","example":"Sprachnormierung."},{"word":"marginalisieren","translation":"to marginalise","pronunciation":"mar-gi-nah-li-ZEE-ren","example":"Sprecher marginalisieren."},{"word":"die Überlegenheit","translation":"superiority","pronunciation":"dee ü-ber-LAY-gen-hyt","example":"Linguistische Überlegenheit."},{"word":"provozieren","translation":"to provoke","pronunciation":"pro-vo-TSEE-ren","example":"Widerstand provozieren."},{"word":"der Beleg","translation":"evidence","pronunciation":"dayr beh-LAYG","example":"Beleg dafür."},{"word":"der Identitätsträger","translation":"carrier of identity","pronunciation":"dayr i-den-ti-TÄTS-trä-ger","example":"Sprache als Identitätsträger."}]}',
'{"title":"Was als X gilt, ist das Ergebnis von Y — what counts as X is the result of Y","pattern":"was als X gilt, ist das Ergebnis von Y = what counts as X is the result of Y (was als X gilt = what counts/passes as X — embedded question/relative clause with gelten als; das Ergebnis von = the result of Y — explains the origin)","explanation":"Was als X gilt = what counts as X, what passes as X (gelten als = to count as, to be regarded as — 3rd person: gilt). Das Ergebnis von Y = the result of Y. Was als ''korrektes'' Deutsch gilt, ist das Ergebnis sozialer Machtverhältnisse = What counts as ''correct'' German is the result of social power relations. The pattern demystifies: it takes something that appears natural or given (what counts as correct) and reveals its contingent social origin. Compare: was gilt als (what counts as — same with different word order), das Ergebnis historischer Prozesse (the result of historical processes — variation), nicht neutral, sondern X (not neutral, but X — simpler version).","examples":[{"sentence":"Was als schön gilt, ist das Ergebnis kultureller Konventionen.","translation":"What counts as beautiful is the result of cultural conventions."},{"sentence":"Was als Fortschritt gilt, ist das Ergebnis politischer Entscheidungen.","translation":"What counts as progress is the result of political decisions."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"''Die Überlegenheit'' means?","options":["superiority","dominance","supremacy","advantage"],"correctAnswer":"superiority"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"Language standardisation is not an objective description, but a political act: the decision of which variety counts as the standard favours speakers of that variety and marginalises others — what counts as ''correct'' German is the result of social power relations, not linguistic superiority.","options":["Sprachnormierung ist keine objektive Beschreibung, sondern ein politischer Akt: Die Entscheidung, welche Varietät als Standard gilt, begünstigt die Sprecher dieser Varietät und marginalisiert andere — was als ''korrektes'' Deutsch gilt, ist das Ergebnis sozialer Machtverhältnisse, nicht linguistischer Überlegenheit.","Standardsprache begünstigt die Sprecher dieser Varietät gegenüber anderen.","Was als ''richtiges'' Deutsch gilt, hat mehr mit Macht als mit Linguistik zu tun.","Sprachstandards sind politische, keine linguistischen Entscheidungen."],"correctAnswer":"Sprachnormierung ist keine objektive Beschreibung, sondern ein politischer Akt: Die Entscheidung, welche Varietät als Standard gilt, begünstigt die Sprecher dieser Varietät und marginalisiert andere — was als ''korrektes'' Deutsch gilt, ist das Ergebnis sozialer Machtverhältnisse, nicht linguistischer Überlegenheit."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Was als schön gilt, ist das Ergebnis kultureller ___.","options":["Konventionen","Normen","Maßstäbe","Standards"],"correctAnswer":"Konventionen"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: What counts as progress is the result of political decisions","wordBankItems":["Was","als","Fortschritt","gilt",",","ist","das","Ergebnis","politischer","Entscheidungen","."],"correctAnswer":"Was als Fortschritt gilt , ist das Ergebnis politischer Entscheidungen ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"''Der Beleg'' means?","options":["evidence","proof","document","record"],"correctAnswer":"evidence"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('aa000000-0000-0000-0000-0000000002d2',1,'APPROVED','PUBLISHED',
'{"objectives":["Discuss dialects and varieties at B2","Use Dialekte und Varietäten vocabulary","Talk about German dialects, Bavarian, Low German, and sociolinguistics of variety"],"explanation":{"intro":"Dialects and varieties vocabulary covers German dialect geography, sociolinguistics, and debates about dialect preservation at B2.","culturalNote":"Dialekte und Varietäten: Germany has extreme dialect diversity (Dialektkontinuum). Key dialects: Bayerisch (Bavaria — very distinct), Sächsisch (Saxon — often mocked), Kölsch (Cologne — not just a beer!), Berlinerisch (Berlin dialect — ''icke'' = ich), Plattdeutsch/Niederdeutsch (Low German — historically distinct language — UNESCO listed). Key sociolinguistic concept: Diglossie (diglossia — two varieties in same community for different functions — High German for formal, Bavarian for home). Social stratification of dialects: dialect = lower status (Dialektsprecher face discrimination). Key: Dialektverlust (dialect decline — Dialektsterben = dialect death — due to education, TV, migration). Key figure: Theodor Siebs (Bühnenaussprache — stage pronunciation — 1898 — codified standard pronunciation). Schweizerdeutsch (Swiss German — very distinct from Standard German — rarely written)."},"examples":[{"german":"Dialekte sind keine fehlerhaften Abweichungen von der Standardsprache, sondern vollständige, regelgeleitete Sprachsysteme: Sie haben eigene Phonologie, Morphologie und Syntax, die von Muttersprachlern unbewusst beherrscht werden, und transportieren kulturelle Bedeutungen, die in der Standardsprache nicht transportierbar sind.","english":"Dialects are not faulty deviations from the standard language, but complete, rule-governed language systems: they have their own phonology, morphology, and syntax that are unconsciously mastered by native speakers, and convey cultural meanings that are not conveyable in the standard language."},{"german":"Dialektsprecher stehen in Deutschland vor einem sprachbiographischen Dilemma: Ihr Dialekt ist Ausdruck von Zugehörigkeit und Identität im lokalen Umfeld, aber sozialer Aufstieg, Bildungserfolg und berufliche Mobilität erfordern oft Angleichung an die Standardsprache — was als sprachliche Kompetenz gemessen wird, reflektiert soziale Herkunft mehr als kognitive Fähigkeit.","english":"Dialect speakers in Germany face a language-biographical dilemma: their dialect is an expression of belonging and identity in the local environment, but social mobility, educational success, and professional mobility often require adaptation to the standard language — what is measured as linguistic competence reflects social origin more than cognitive ability."}],"rewards":{"xp":150,"coins":80},"metadata":{"estimatedMinutes":20,"canDo":"I can discuss German dialect geography, diglossia, and the social status of dialects at B2."}}',
'{"items":[{"word":"regelgeleitet","translation":"rule-governed","pronunciation":"RAY-gel-geh-ly-tet","example":"Regelgeleitetes Sprachsystem."},{"word":"die Morphologie","translation":"morphology","pronunciation":"dee mor-fo-lo-GEE","example":"Morphologie des Dialekts."},{"word":"unbewusst","translation":"unconsciously","pronunciation":"oon-beh-VOOST","example":"Unbewusst beherrschen."},{"word":"der Aufstieg","translation":"mobility/rise","pronunciation":"dayr OWF-shteek","example":"Sozialer Aufstieg."},{"word":"die Angleichung","translation":"adaptation/assimilation","pronunciation":"dee AN-gly-khoong","example":"Angleichung an Standard."},{"word":"die Herkunft","translation":"origin","pronunciation":"dee HAYR-koonft","example":"Soziale Herkunft."}]}',
'{"title":"Reflektiert X mehr als Y — reflects X more than Y (what something actually measures)","pattern":"etwas reflektiert X mehr als Y = something reflects X more than Y (reflektieren = to reflect; mehr als = more than; marks that the apparent measure X is actually a measure of something else Y)","explanation":"Reflektiert X mehr als Y = reflects X more than Y. Was als sprachliche Kompetenz gemessen wird, reflektiert soziale Herkunft mehr als kognitive Fähigkeit = What is measured as linguistic competence reflects social origin more than cognitive ability. The pattern reveals a discrepancy between what something claims to measure (Y — linguistic competence) and what it actually reflects (X — social origin). Often used critically to question validity of tests, assessments, or categories. Compare: misst tatsächlich X, nicht Y (actually measures X, not Y — more direct), ist ein Proxy für X (is a proxy for X — more technical), tatsächlich ein Indikator für X (actually an indicator of X).","examples":[{"sentence":"Schulnoten reflektieren soziale Herkunft mehr als individuelle Leistung.","translation":"School grades reflect social origin more than individual performance."},{"sentence":"Die Umfrageergebnisse reflektieren Framing-Effekte mehr als wahre Präferenzen.","translation":"The survey results reflect framing effects more than true preferences."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"''Regelgeleitet'' means?","options":["rule-governed","systematic","principled","structured"],"correctAnswer":"rule-governed"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"Dialects are not faulty deviations from the standard language, but complete, rule-governed language systems: they have their own phonology, morphology, and syntax that are unconsciously mastered by native speakers, and convey cultural meanings that are not conveyable in the standard language.","options":["Dialekte sind keine fehlerhaften Abweichungen von der Standardsprache, sondern vollständige, regelgeleitete Sprachsysteme: Sie haben eigene Phonologie, Morphologie und Syntax, die von Muttersprachlern unbewusst beherrscht werden, und transportieren kulturelle Bedeutungen, die in der Standardsprache nicht transportierbar sind.","Dialekte sind vollständige Sprachsysteme, keine Fehler.","Dialekte haben eigene grammatische Regeln und kulturelle Bedeutungen.","Dialekte sind linguistisch genauso komplex wie Standardsprachen."],"correctAnswer":"Dialekte sind keine fehlerhaften Abweichungen von der Standardsprache, sondern vollständige, regelgeleitete Sprachsysteme: Sie haben eigene Phonologie, Morphologie und Syntax, die von Muttersprachlern unbewusst beherrscht werden, und transportieren kulturelle Bedeutungen, die in der Standardsprache nicht transportierbar sind."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Schulnoten reflektieren soziale Herkunft mehr als individuelle ___.","options":["Leistung","Kompetenz","Fähigkeit","Intelligenz"],"correctAnswer":"Leistung"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: The survey results reflect framing effects more than true preferences","wordBankItems":["Die","Umfrageergebnisse","reflektieren","Framing-Effekte","mehr","als","wahre","Präferenzen","."],"correctAnswer":"Die Umfrageergebnisse reflektieren Framing-Effekte mehr als wahre Präferenzen ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"''Die Angleichung'' means?","options":["adaptation/assimilation","alignment","adjustment","approximation"],"correctAnswer":"adaptation/assimilation"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('aa000000-0000-0000-0000-0000000002d3',1,'APPROVED','PUBLISHED',
'{"objectives":["Discuss multilingualism at B2","Use Mehrsprachigkeit vocabulary","Talk about Germany''s multilingual reality, heritage languages, and bilingual education"],"explanation":{"intro":"Multilingualism vocabulary covers Germany''s linguistic diversity, heritage languages, and bilingual education at B2.","culturalNote":"Mehrsprachigkeit: Germany: ~20% of population have migration background; most common heritage languages: Turkish (~2.8m), Russian (~2m), Polish (~1.5m), Arabic, Italian. Key: Herkunftssprachen (heritage languages — school debate — only some Bundesländer offer Turkish/Russian at school). Bilingualer Unterricht (bilingual instruction — CLIL — Content and Language Integrated Learning). Key concept: Code-switching (switching between languages in discourse — perfectly normal for bilinguals). Additive vs. Subtraktive Zweisprachigkeit (additive: both languages thrive; subtractive: L1 is lost as L2 is acquired). Schriftliche vs. Mündliche Kompetenz. Key figure: François Grosjean (bilinguals are not two monolinguals in one). Kiezsprache (multiethnic youth vernacular — Berlin — mix of German, Turkish, Arabic). Deutsch als Zweitsprache (German as second language — DaZ — not same as DaF)."},"examples":[{"german":"Mehrsprachigkeit ist kein Ausnahmezustand, sondern der weltweite Normalfall: Die Mehrheit der Menschen auf der Erde spricht mehr als eine Sprache — Einsprachigkeit, die in Europa als Norm gilt, ist global die Ausnahme. Zweisprachig aufgewachsene Kinder erwerben beide Sprachen vollständig, sofern sie ausreichend Input in beiden erhalten.","english":"Multilingualism is not an exceptional state, but the global norm: the majority of people on earth speak more than one language — monolingualism, which counts as the norm in Europe, is the global exception. Children raised bilingually acquire both languages fully, provided they receive sufficient input in both."},{"german":"Code-switching ist kein Zeichen sprachlicher Defizite, sondern eine sophistizierte kommunikative Kompetenz: Zweisprachige Sprecher wechseln zwischen ihren Sprachen aus pragmatischen Gründen — Identitätssignalisierung, Domänenmarkierung, Effizienz — und folgen dabei unbewussten grammatischen Regeln, die den Wechsel regulieren.","english":"Code-switching is not a sign of linguistic deficits, but a sophisticated communicative competence: bilingual speakers switch between their languages for pragmatic reasons — identity signalling, domain marking, efficiency — and follow unconscious grammatical rules regulating the switch."}],"rewards":{"xp":150,"coins":80},"metadata":{"estimatedMinutes":20,"canDo":"I can discuss multilingualism, code-switching, and Germany''s heritage language situation at B2."}}',
'{"items":[{"word":"der Ausnahmezustand","translation":"exceptional state","pronunciation":"dayr OWS-nah-meh-tsoo-shtant","example":"Kein Ausnahmezustand."},{"word":"sofern","translation":"provided that/as long as","pronunciation":"zo-FERN","example":"Sofern Bedingungen erfüllt."},{"word":"sophistiziert","translation":"sophisticated","pronunciation":"zo-fis-ti-TSIERT","example":"Sophistizierte Kompetenz."},{"word":"das Signalisieren","translation":"signalling","pronunciation":"dahs zig-nah-li-ZEE-ren","example":"Identitätssignalisierung."},{"word":"die Effizienz","translation":"efficiency","pronunciation":"dee ef-fi-TSIENZ","example":"Kommunikative Effizienz."},{"word":"regulieren","translation":"to regulate","pronunciation":"reh-goo-LEER-en","example":"Den Wechsel regulieren."}]}',
'{"title":"Sofern X — provided that X (conditional fulfillment)","pattern":"etwas gelingt, sofern X = something succeeds, provided that X (sofern = provided that, as long as — conditional conjunction — marks a necessary but sufficient condition for the main clause to hold)","explanation":"Sofern = provided that, as long as (sofern introduces a conditional that must be met for the main clause to hold — stronger than wenn/if, closer to ''provided that'' — implying the condition is often not met). Kinder erwerben beide Sprachen vollständig, sofern sie ausreichend Input erhalten = Children acquire both languages fully, provided they receive sufficient input. Sofern can stand initially or after main clause (sofern X, Y or Y, sofern X). Compare: vorausgesetzt, dass (provided that — more formal synonym), wenn (if — more neutral/probable condition), unter der Bedingung, dass (under the condition that — more explicit), falls (in case/if — possibility), solange (as long as — temporal condition).","examples":[{"sentence":"Das Projekt gelingt, sofern alle Beteiligten kooperieren.","translation":"The project succeeds, provided all participants cooperate."},{"sentence":"Sofern keine Einwände bestehen, können wir beginnen.","translation":"Provided there are no objections, we can begin."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"''Sophistiziert'' means?","options":["sophisticated","refined","advanced","complex"],"correctAnswer":"sophisticated"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"Multilingualism is not an exceptional state, but the global norm: the majority of people on earth speak more than one language — monolingualism, which counts as the norm in Europe, is the global exception. Children raised bilingually acquire both languages fully, provided they receive sufficient input in both.","options":["Mehrsprachigkeit ist kein Ausnahmezustand, sondern der weltweite Normalfall: Die Mehrheit der Menschen auf der Erde spricht mehr als eine Sprache — Einsprachigkeit, die in Europa als Norm gilt, ist global die Ausnahme. Zweisprachig aufgewachsene Kinder erwerben beide Sprachen vollständig, sofern sie ausreichend Input in beiden erhalten.","Weltweit sind die meisten Menschen mehrsprachig — Einsprachigkeit ist die Ausnahme.","Kinder können problemlos zwei Sprachen gleichzeitig erwerben.","Mehrsprachigkeit ist global verbreitet; Europa ist mit seiner Einsprachigkeitsnorm die Ausnahme."],"correctAnswer":"Mehrsprachigkeit ist kein Ausnahmezustand, sondern der weltweite Normalfall: Die Mehrheit der Menschen auf der Erde spricht mehr als eine Sprache — Einsprachigkeit, die in Europa als Norm gilt, ist global die Ausnahme. Zweisprachig aufgewachsene Kinder erwerben beide Sprachen vollständig, sofern sie ausreichend Input in beiden erhalten."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Das Projekt gelingt, sofern alle Beteiligten ___.","options":["kooperieren","mitmachen","zusammenarbeiten","teilnehmen"],"correctAnswer":"kooperieren"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: Provided there are no objections we can begin","wordBankItems":["Sofern","keine","Einwände","bestehen",",","können","wir","beginnen","."],"correctAnswer":"Sofern keine Einwände bestehen , können wir beginnen ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"''Das Signalisieren'' means?","options":["signalling","indicating","marking","communicating"],"correctAnswer":"signalling"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('aa000000-0000-0000-0000-0000000002d4',1,'APPROVED','PUBLISHED',
'{"objectives":["Discuss foreign language acquisition at B2","Use Fremdsprachenerwerb vocabulary","Talk about language acquisition theory, Critical Period Hypothesis, and German language learning"],"explanation":{"intro":"Foreign language acquisition vocabulary covers SLA theory, the Critical Period Hypothesis, and German as a foreign language at B2.","culturalNote":"Fremdsprachenerwerb: Key SLA theories: Krashen (Input Hypothesis — i+1 — comprehensible input; Monitor Hypothesis; Affective Filter). Critical Period Hypothesis (Lenneberg 1967 — children acquire L1 effortlessly; L2 after puberty = more difficulty — age of acquisition matters). Universal Grammar (Chomsky — Language Acquisition Device — innate language faculty). Interaction Hypothesis (Long). Output Hypothesis (Swain — production forces noticing). Key German context: Deutsch als Fremdsprache (DaF) — German taught worldwide in ~70,000 schools and universities. Cases (Nominativ, Akkusativ, Dativ, Genitiv) — notoriously difficult for speakers of non-case languages. CEFR (A1-C2 — Common European Framework of Reference). Interimsprache (interlanguage — Selinker 1972)."},"examples":[{"german":"Fremdsprachenerwerb ist kein Abkopieren des Erstspracherwerbs: Erwachsene Lernende verfügen über analytische Fähigkeiten, konzeptuelle Strukturen und metalinguistisches Bewusstsein, die den Erwerbsprozess in quantitativer und qualitativer Hinsicht vom kindlichen L1-Erwerb unterscheiden — was für Kinder implizit und unbewusst abläuft, erfordert von Erwachsenen oft explizite Regelkenntnis.","english":"Foreign language acquisition is not a copy of first language acquisition: adult learners possess analytical abilities, conceptual structures, and metalinguistic awareness that distinguish the acquisition process from childhood L1 acquisition both quantitatively and qualitatively — what proceeds implicitly and unconsciously for children often requires explicit rule knowledge from adults."},{"german":"Die Interimsprache ist ein eigenständiges Sprachsystem, kein Fehlerprodukt: Sie ist systematisch, regelgeleitet und entwickelt sich — so wie jede Sprache — durch zunehmenden Input, Interaktion und Überprüfung von Hypothesen über die Zielsprache. Fehler sind deshalb keine Zeichen des Scheiterns, sondern diagnostisch wertvolle Hypothesentests.","english":"Interlanguage is an independent language system, not a defective product: it is systematic, rule-governed, and develops — like any language — through increasing input, interaction, and testing of hypotheses about the target language. Errors are therefore not signs of failure, but diagnostically valuable hypothesis tests."}],"rewards":{"xp":150,"coins":80},"metadata":{"estimatedMinutes":20,"canDo":"I can discuss SLA theory, interlanguage, and adult vs. child language acquisition at B2."}}',
'{"items":[{"word":"metalinguistisch","translation":"metalinguistic","pronunciation":"meh-tah-lin-GWIS-tish","example":"Metalinguistisches Bewusstsein."},{"word":"quantitativ","translation":"quantitative","pronunciation":"kvan-ti-tah-TEEF","example":"Quantitative Unterschiede."},{"word":"implizit","translation":"implicit","pronunciation":"im-PLI-tsit","example":"Implizit erwerben."},{"word":"die Interimsprache","translation":"interlanguage","pronunciation":"dee in-teh-RIMS-shprah-kheh","example":"Interimsprache als System."},{"word":"diagnostisch","translation":"diagnostic","pronunciation":"di-ag-NOS-tish","example":"Diagnostisch wertvoll."},{"word":"die Hypothese","translation":"hypothesis","pronunciation":"dee hy-po-TAY-zeh","example":"Sprachhypothesen testen."}]}',
'{"title":"Etwas ist ein eigenständiges X, kein Y — something is an independent X, not a defective Y","pattern":"etwas ist ein eigenständiges X, kein Y = something is an independent X, not a Y (eigenständig = independent, standing on its own; kein + noun = not a...— denies a deficiency characterisation and replaces with a positive one)","explanation":"Eigenständig = independent, standing on its own (not derived from, dependent on, or a defective version of something else). Die Interimsprache ist ein eigenständiges Sprachsystem, kein Fehlerprodukt = Interlanguage is an independent language system, not a defective product. The pattern reframes by refusing a negative definition (kein Y = not a Y, where Y implies deficit or derivativeness) and asserting an autonomous positive identity (ein eigenständiges X). Compare: sui generis (of its own kind — Latin), in sich geschlossen (self-contained), vollständig in seiner Art (complete in its own kind), ein X eigenen Rechts (an X in its own right).","examples":[{"sentence":"Das ist ein eigenständiges Forschungsfeld, kein Nebengebiet.","translation":"This is an independent research field, not a subdiscipline."},{"sentence":"Der Dialekt ist ein eigenständiges Sprachsystem, kein fehlerhaftes Deutsch.","translation":"The dialect is an independent language system, not faulty German."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"''Metalinguistisch'' means?","options":["metalinguistic","about language","language-aware","reflective of language"],"correctAnswer":"metalinguistic"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"Interlanguage is an independent language system, not a defective product: it is systematic, rule-governed, and develops — like any language — through increasing input, interaction, and testing of hypotheses about the target language. Errors are therefore not signs of failure, but diagnostically valuable hypothesis tests.","options":["Die Interimsprache ist ein eigenständiges Sprachsystem, kein Fehlerprodukt: Sie ist systematisch, regelgeleitet und entwickelt sich — so wie jede Sprache — durch zunehmenden Input, Interaktion und Überprüfung von Hypothesen über die Zielsprache. Fehler sind deshalb keine Zeichen des Scheiterns, sondern diagnostisch wertvolle Hypothesentests.","Fehler beim Sprachenlernen sind keine Misserfolge, sondern normale Lernschritte.","Die Interimsprache ist systematisch und kein Zeichen von Versagen.","Lernerfehler sind wertvolle Einblicke in den Erwerbsprozess."],"correctAnswer":"Die Interimsprache ist ein eigenständiges Sprachsystem, kein Fehlerprodukt: Sie ist systematisch, regelgeleitet und entwickelt sich — so wie jede Sprache — durch zunehmenden Input, Interaktion und Überprüfung von Hypothesen über die Zielsprache. Fehler sind deshalb keine Zeichen des Scheiterns, sondern diagnostisch wertvolle Hypothesentests."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Das ist ein eigenständiges Forschungsfeld, kein ___.","options":["Nebengebiet","Teilgebiet","Untergebiet","Randgebiet"],"correctAnswer":"Nebengebiet"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: The dialect is an independent language system not faulty German","wordBankItems":["Der","Dialekt","ist","ein","eigenständiges","Sprachsystem",",","kein","fehlerhaftes","Deutsch","."],"correctAnswer":"Der Dialekt ist ein eigenständiges Sprachsystem , kein fehlerhaftes Deutsch ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"''Diagnostisch'' means?","options":["diagnostic","indicative","revealing","informative"],"correctAnswer":"diagnostic"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('aa000000-0000-0000-0000-0000000002d5',1,'APPROVED','PUBLISHED',
'{"objectives":["Discuss media language at B2","Use Mediensprache vocabulary","Talk about journalistic language, media framing, and how language shapes news"],"explanation":{"intro":"Media language vocabulary covers journalistic language, framing effects, and critical media literacy at B2.","culturalNote":"Mediensprache: Key concept: Framing (media framing — how stories are told shapes how they are understood). Key journals: Süddeutsche Zeitung, FAZ (Frankfurter Allgemeine Zeitung), Die Zeit, Spiegel, taz. Quality press vs. Boulevardpresse (tabloid — Bild-Zeitung — highest circulation in Germany ~3m/day). Sprachkritik (language criticism — e.g. ''Unwort des Jahres'' — Word of the Year / Unwort = un-word — selected annually since 1991 by jury — e.g. ''Klimaterroristen'', ''Lügenpresse''). Key: passive voice and nominalisation in media language — obscures agency. Nachrichtenwert (news value — Galtung & Ruge — proximity, unexpectedness, elite persons/nations). Cliffhanger, Sensationalismus (sensationalism). Key: Politische Kommunikation (political communication — spin, Agenda-Setting — McCombs & Shaw)."},"examples":[{"german":"Mediensprache formt die Wirklichkeitswahrnehmung, ohne dies transparent zu machen: Welche Ereignisse als Nachrichten gelten, welche Akteure als Hauptpersonen erscheinen und welche Kausalattributionen vorgenommen werden, sind redaktionelle Entscheidungen, die den Verstehensprozess der Rezipienten lenken, bevor diese überhaupt bewusst anfangen, eine Geschichte zu bewerten.","english":"Media language shapes the perception of reality without making this transparent: which events count as news, which actors appear as main figures, and which causal attributions are made are editorial decisions that direct the recipients'' process of understanding even before they consciously begin to evaluate a story."},{"german":"Nominalstil und Passivkonstruktionen in der Berichterstattung sind keine stilistischen Spielereien: Indem sie handelnde Subjekte verbergen und Prozesse zu Dingen verdinglichten, entziehen sie politische Entscheidungen der demokratischen Zurechnung — wer entschieden hat und wer verantwortlich ist, verschwimmt hinter abstrakten Substantiven und unpersönlichen Konstruktionen.","english":"Nominal style and passive constructions in reporting are not stylistic games: by concealing acting subjects and reifying processes into things, they withdraw political decisions from democratic attribution — who decided and who is responsible blurs behind abstract nouns and impersonal constructions."}],"rewards":{"xp":150,"coins":80},"metadata":{"estimatedMinutes":20,"canDo":"I can discuss media framing, journalistic language, and the politics of nominalisation at B2."}}',
'{"items":[{"word":"die Wahrnehmung","translation":"perception","pronunciation":"dee VAR-nay-moong","example":"Wirklichkeitswahrnehmung."},{"word":"die Kausalattribution","translation":"causal attribution","pronunciation":"dee kow-ZAHL-ah-tri-boo-tsyohn","example":"Kausalattributionen vornehmen."},{"word":"lenken","translation":"to direct/steer","pronunciation":"LENG-ken","example":"Verstehensprozess lenken."},{"word":"verdinglicht","translation":"reified","pronunciation":"fer-DING-likht","example":"Prozesse verdinglicht."},{"word":"die Zurechnung","translation":"attribution","pronunciation":"dee TSOO-rekh-noong","example":"Demokratische Zurechnung."},{"word":"verschwimmen","translation":"to blur","pronunciation":"fer-SHVIM-en","example":"Verantwortung verschwimmt."}]}',
'{"title":"Bevor X überhaupt bewusst anfangen Y zu tun — before X even consciously begins to do Y","pattern":"bevor X überhaupt bewusst anfängt, Y zu tun = before X even consciously begins to do Y (bevor = before — temporal subordination; überhaupt = at all/even; bewusst = consciously; anfangen + infinitive + zu)","explanation":"Bevor X überhaupt... = before X even... (überhaupt adds emphasis: not even yet, not at all yet). Bevor Rezipienten überhaupt bewusst anfangen, eine Geschichte zu bewerten = Before recipients even consciously begin to evaluate a story. The phrase marks pre-conscious or pre-reflective influence: the effect happens before the person is even aware that evaluation is occurring. Anfangen + zu + infinitive = to begin to do. Compare: ohne dass X es merkt (without X noticing it), bevor X reagieren kann (before X can react — reaction-based), noch bevor X weiß (even before X knows).","examples":[{"sentence":"Bevor der Nutzer überhaupt bewusst anfängt zu lesen, lenkt das Layout seinen Blick.","translation":"Before the user even consciously begins to read, the layout directs their gaze."},{"sentence":"Bevor wir überhaupt anfangen zu denken, verarbeiten wir emotionale Reize.","translation":"Before we even begin to think, we process emotional stimuli."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"''Verschwimmen'' means?","options":["to blur","to fade","to blend","to merge"],"correctAnswer":"to blur"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"Media language shapes the perception of reality without making this transparent: which events count as news, which actors appear as main figures, and which causal attributions are made are editorial decisions that direct the recipients'' process of understanding even before they consciously begin to evaluate a story.","options":["Mediensprache formt die Wirklichkeitswahrnehmung, ohne dies transparent zu machen: Welche Ereignisse als Nachrichten gelten, welche Akteure als Hauptpersonen erscheinen und welche Kausalattributionen vorgenommen werden, sind redaktionelle Entscheidungen, die den Verstehensprozess der Rezipienten lenken, bevor diese überhaupt bewusst anfangen, eine Geschichte zu bewerten.","Framing in Medien steuert die Wahrnehmung, ohne dass Rezipienten es merken.","Mediensprache beeinflusst, wie wir Ereignisse verstehen, noch bevor wir sie bewerten.","Journalisten wählen aus, was als Nachricht gilt und wer die Hauptrolle spielt."],"correctAnswer":"Mediensprache formt die Wirklichkeitswahrnehmung, ohne dies transparent zu machen: Welche Ereignisse als Nachrichten gelten, welche Akteure als Hauptpersonen erscheinen und welche Kausalattributionen vorgenommen werden, sind redaktionelle Entscheidungen, die den Verstehensprozess der Rezipienten lenken, bevor diese überhaupt bewusst anfangen, eine Geschichte zu bewerten."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Bevor der Nutzer überhaupt bewusst anfängt zu lesen, lenkt das Layout seinen ___.","options":["Blick","Fokus","Blickwinkel","Aufmerksamkeit"],"correctAnswer":"Blick"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: Before we even begin to think we process emotional stimuli","wordBankItems":["Bevor","wir","überhaupt","anfangen","zu","denken",",","verarbeiten","wir","emotionale","Reize","."],"correctAnswer":"Bevor wir überhaupt anfangen zu denken , verarbeiten wir emotionale Reize ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"''Die Zurechnung'' means?","options":["attribution","accountability","assignment","liability"],"correctAnswer":"attribution"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('aa000000-0000-0000-0000-0000000002d6',1,'APPROVED','PUBLISHED',
'{"objectives":["Discuss rhetoric and persuasion at B2","Use Rhetorik und Überzeugung vocabulary","Talk about classical rhetoric, argumentation theory, and political persuasion"],"explanation":{"intro":"Rhetoric and persuasion vocabulary covers classical rhetoric, modern argumentation theory, and political communication at B2.","culturalNote":"Rhetorik und Überzeugung: Classical rhetoric: Aristotle — three modes of persuasion: Ethos (character/credibility), Logos (logic/evidence), Pathos (emotion). Cicero (De Oratore). Five canons: Inventio (finding arguments), Dispositio (arrangement), Elocutio (style), Memoria (memory), Actio (delivery). German: Bundestagsdebatte — relatively sober parliamentary oratory. Key modern: Toulmin Modell (claim + grounds + warrant + backing + qualifier + rebuttal). Argumentationstheorie (argumentation theory — Perelman). Fallacies (argumentative errors): Strohmann (straw man), Ad hominem, False Dichotomy. Key concept: Kairos (the right moment). Political rhetoric: soundbite culture, Framing. Deliberative Demokratie (deliberative democracy — Habermas — rational discourse). Cicero''s ideal: ''vir bonus dicendi peritus'' — ''a good man skilled in speaking''."},"examples":[{"german":"Aristoteles unterscheidet drei Überzeugungsmittel: Ethos — die Glaubwürdigkeit des Sprechers, die den Rezipienten vertrauensbildend stimmt; Logos — das Argument, das die Vernunft anspricht; und Pathos — der emotionale Appell, der Affekte mobilisiert. Wirksame Rhetorik integriert alle drei, weil Menschen nicht nur als rationale Entscheidungsträger, sondern als verkörperte soziale Wesen angesprochen werden müssen.","english":"Aristotle distinguishes three means of persuasion: ethos — the credibility of the speaker, which puts the recipient in a trust-building frame of mind; logos — the argument that addresses reason; and pathos — the emotional appeal that mobilises affects. Effective rhetoric integrates all three, because people must be addressed not only as rational decision-makers, but as embodied social beings."},{"german":"Rhetorische Kompetenz schließt die Fähigkeit ein, Scheinargumenten zu widerstehen: Der Strohmann-Trugschluss substituiert das tatsächliche Argument des Gegners durch eine schwächere Version, die leichter zu widerlegen ist; Ad-hominem-Angriffe attackieren den Sprecher statt das Argument — Techniken, die in politischen Debatten häufig vorkommen und kritisches Hören erfordern.","english":"Rhetorical competence includes the capacity to resist specious arguments: the straw man fallacy substitutes the opponent''s actual argument with a weaker version that is easier to refute; ad hominem attacks attack the speaker rather than the argument — techniques that occur frequently in political debates and require critical listening."}],"rewards":{"xp":150,"coins":80},"metadata":{"estimatedMinutes":20,"canDo":"I can discuss Aristotle''s rhetoric, the Toulmin model, and argumentation fallacies at B2."}}',
'{"items":[{"word":"die Glaubwürdigkeit","translation":"credibility","pronunciation":"dee GLOWP-vür-dikh-kyt","example":"Glaubwürdigkeit des Sprechers."},{"word":"vertrauensbildend","translation":"trust-building","pronunciation":"fer-TROW-ens-bil-dend","example":"Vertrauensbildend stimmen."},{"word":"das Überzeugungsmittel","translation":"means of persuasion","pronunciation":"dahs ü-ber-TSOY-goonks-mi-tel","example":"Drei Überzeugungsmittel."},{"word":"der Trugschluss","translation":"fallacy","pronunciation":"dayr TROOK-shloos","example":"Rhetorischer Trugschluss."},{"word":"substituieren","translation":"to substitute","pronunciation":"zoob-sti-too-EE-ren","example":"Argument substituieren."},{"word":"widerlegen","translation":"to refute","pronunciation":"VEE-der-lay-gen","example":"Argument widerlegen."}]}',
'{"title":"X schließt die Fähigkeit ein, Y zu tun — X includes the capacity to do Y","pattern":"X schließt die Fähigkeit ein, Y zu tun = X includes the capacity to do Y (einschließen = to include — separable: schließt...ein; die Fähigkeit + zu + infinitive = capacity to do; X is broader than Y, which is one component of X)","explanation":"Einschließen = to include (separable: schließt...ein — schließt die Fähigkeit ein = includes the capacity). Rhetorical competence includes the capacity to resist specious arguments: X (rhetorical competence) includes Y (capacity to resist). The pattern is used to enumerate capacities or components of a broader concept. Die Fähigkeit + zu + infinitive = the capacity/ability to + verb. Compare: beinhalten (to contain/involve — more technical), umfassen (to encompass — broader), voraussetzen (to presuppose — different relationship), gehören zu (to belong to X — from the opposite direction).","examples":[{"sentence":"Wissenschaftliche Integrität schließt die Fähigkeit ein, Fehler zuzugeben.","translation":"Scientific integrity includes the capacity to admit mistakes."},{"sentence":"Führungskompetenz schließt die Fähigkeit ein, Entscheidungen zu delegieren.","translation":"Leadership competence includes the capacity to delegate decisions."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"''Der Trugschluss'' means?","options":["fallacy","sophism","logical error","reasoning error"],"correctAnswer":"fallacy"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"Rhetorical competence includes the capacity to resist specious arguments: the straw man fallacy substitutes the opponent''s actual argument with a weaker version that is easier to refute; ad hominem attacks attack the speaker rather than the argument — techniques that occur frequently in political debates and require critical listening.","options":["Rhetorische Kompetenz schließt die Fähigkeit ein, Scheinargumenten zu widerstehen: Der Strohmann-Trugschluss substituiert das tatsächliche Argument des Gegners durch eine schwächere Version, die leichter zu widerlegen ist; Ad-hominem-Angriffe attackieren den Sprecher statt das Argument — Techniken, die in politischen Debatten häufig vorkommen und kritisches Hören erfordern.","Rhetorische Kompetenz bedeutet, Argumente zu erkennen und Trugschlüsse zu vermeiden.","Strohmann und Ad hominem sind häufige Fehler in politischen Debatten.","Kritisches Hören hilft, rhetorische Tricks zu durchschauen."],"correctAnswer":"Rhetorische Kompetenz schließt die Fähigkeit ein, Scheinargumenten zu widerstehen: Der Strohmann-Trugschluss substituiert das tatsächliche Argument des Gegners durch eine schwächere Version, die leichter zu widerlegen ist; Ad-hominem-Angriffe attackieren den Sprecher statt das Argument — Techniken, die in politischen Debatten häufig vorkommen und kritisches Hören erfordern."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Wissenschaftliche Integrität schließt die Fähigkeit ein, Fehler ___.","options":["zuzugeben","zuzugestehen","anzuerkennen","einzugestehen"],"correctAnswer":"zuzugeben"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: Leadership competence includes the capacity to delegate decisions","wordBankItems":["Führungskompetenz","schließt","die","Fähigkeit","ein",",","Entscheidungen","zu","delegieren","."],"correctAnswer":"Führungskompetenz schließt die Fähigkeit ein , Entscheidungen zu delegieren ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"''Widerlegen'' means?","options":["to refute","to disprove","to rebut","to counter"],"correctAnswer":"to refute"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('aa000000-0000-0000-0000-0000000002d7',1,'APPROVED','PUBLISHED',
'{"objectives":["Discuss academic language at B2","Use Wissenschaftssprache vocabulary","Talk about academic German style, argumentation, and the language of scholarship"],"explanation":{"intro":"Academic language vocabulary covers German scholarly writing conventions, argumentation patterns, and the distinctive register of German Wissenschaftssprache at B2.","culturalNote":"Wissenschaftssprache: German academic language: Nominalstil (nominal style — heavy use of nouns — Substantivierung), Passivkonstruktionen (passive constructions), long sentences, Subjunktiv II for hedging. Key concept: German ''Wissenschaft'' (scholarship/science — broader than English ''science'' — includes humanities). Key tradition: Hermeneutik (hermeneutics — understanding texts — Gadamer), Diskursanalyse (discourse analysis — Foucault influence). German PhD: traditionally 5 years, independent research, Monographie. Key: Theodor Adorno (''Der Essay als Form'' — essay as philosophical form — resistance to system). Deutsche Forschungsgemeinschaft (DFG — German Research Foundation — key funding body). Wissenschaftspropädeutik (propaedeutics to academic work). Zitierstil (citation style — German conventions differ: footnotes common). Key: ''Die Fußnote ist die Seele des deutschen Buches'' (The footnote is the soul of the German book)."},"examples":[{"german":"Akademisches Schreiben ist keine neutrale Wiedergabe von Fakten, sondern eine argumentative Praxis: Wissenschaftliche Texte verfolgen eine These, mobilisieren Belege, entkräften Gegenargumente und situieren ihre Aussagen innerhalb eines Diskurses — eine Struktur, die implizit bleibt, wenn sie nicht explizit geübt wird, und die Studierende oft erst spät erkennen.","english":"Academic writing is not a neutral reproduction of facts, but an argumentative practice: scholarly texts pursue a thesis, mobilise evidence, defuse counter-arguments, and situate their claims within a discourse — a structure that remains implicit if it is not explicitly practised, and that students often recognise only late."},{"german":"Der deutsche Nominalstil verdichtet Bedeutung auf Kosten der Lesbarkeit: Substantivierungen wie ''Indienstnahme'', ''Ermächtigung'' oder ''Problematisierung'' komprimieren komplexe Prozesse in ein Wort, was Texte informationsdicht, aber auch anfällig für Unverständlichkeit macht — eine Spannung, die Wissenschaftler zwischen Präzision und Zugänglichkeit entscheiden lässt.","english":"German nominal style compresses meaning at the cost of readability: nominalisations like ''co-optation'', ''authorisation'', or ''problematisation'' compress complex processes into one word, making texts information-dense but also susceptible to incomprehensibility — a tension that leaves scholars to decide between precision and accessibility."}],"rewards":{"xp":150,"coins":80},"metadata":{"estimatedMinutes":20,"canDo":"I can discuss German academic language, nominal style, and the structure of scholarly argument at B2."}}',
'{"items":[{"word":"entkräften","translation":"to defuse/rebut","pronunciation":"ent-KREF-ten","example":"Gegenargumente entkräften."},{"word":"situieren","translation":"to situate","pronunciation":"zi-too-EE-ren","example":"Aussagen situieren."},{"word":"die Substantivierung","translation":"nominalisation","pronunciation":"dee zoob-stan-ti-VEE-roong","example":"Substantivierungen."},{"word":"verdichten","translation":"to compress/densify","pronunciation":"fer-DIKH-ten","example":"Bedeutung verdichten."},{"word":"anfällig","translation":"susceptible","pronunciation":"AN-fä-likh","example":"Anfällig für Fehler."},{"word":"die Zugänglichkeit","translation":"accessibility","pronunciation":"dee TSOO-geng-likh-kyt","example":"Zugänglichkeit vs. Präzision."}]}',
'{"title":"X bleibt implizit, wenn es nicht explizit Y wird — X remains implicit if it is not explicitly Y","pattern":"etwas bleibt implizit, wenn es nicht explizit X wird = something remains implicit if it is not explicitly X-ed (bleibt implizit = remains implicit — implicit/tacit unless drawn out; wenn...nicht...explizit...wird — conditional with negation)","explanation":"Bleibt implizit = remains implicit (implicit = not stated/visible; explicit = stated/made visible). Die Struktur bleibt implizit, wenn sie nicht explizit geübt wird = The structure remains implicit if it is not explicitly practised. The pattern marks the need to make tacit knowledge explicit through deliberate practice or teaching. Common in pedagogical, epistemological, and social-scientific contexts. Compare: stillschweigend vorausgesetzt (tacitly presupposed), selbstverständlich (taken for granted — more positive), latent (latent — more psychological), unsichtbar (invisible — more visual metaphor), in Praxis eingebettet (embedded in practice — Polanyi: tacit knowledge).","examples":[{"sentence":"Das Regelwissen bleibt implizit, wenn Lernende es nie explizit artikulieren.","translation":"The rule knowledge remains implicit if learners never explicitly articulate it."},{"sentence":"Vorurteile bleiben implizit, wenn sie nicht explizit reflektiert werden.","translation":"Prejudices remain implicit if they are not explicitly reflected upon."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"''Entkräften'' means?","options":["to defuse/rebut","to invalidate","to weaken","to neutralise"],"correctAnswer":"to defuse/rebut"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"Academic writing is not a neutral reproduction of facts, but an argumentative practice: scholarly texts pursue a thesis, mobilise evidence, defuse counter-arguments, and situate their claims within a discourse — a structure that remains implicit if it is not explicitly practised, and that students often recognise only late.","options":["Akademisches Schreiben ist keine neutrale Wiedergabe von Fakten, sondern eine argumentative Praxis: Wissenschaftliche Texte verfolgen eine These, mobilisieren Belege, entkräften Gegenargumente und situieren ihre Aussagen innerhalb eines Diskurses — eine Struktur, die implizit bleibt, wenn sie nicht explizit geübt wird, und die Studierende oft erst spät erkennen.","Wissenschaftliche Texte vertreten eine These und entkräften Gegenargumente.","Akademisches Schreiben folgt einer argumentativen Struktur, die explizit gelehrt werden muss.","Studierende müssen die argumentative Struktur von Wissenschaftstexten explizit lernen."],"correctAnswer":"Akademisches Schreiben ist keine neutrale Wiedergabe von Fakten, sondern eine argumentative Praxis: Wissenschaftliche Texte verfolgen eine These, mobilisieren Belege, entkräften Gegenargumente und situieren ihre Aussagen innerhalb eines Diskurses — eine Struktur, die implizit bleibt, wenn sie nicht explizit geübt wird, und die Studierende oft erst spät erkennen."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Das Regelwissen bleibt implizit, wenn Lernende es nie explizit ___.","options":["artikulieren","ausdrücken","verbalisieren","formulieren"],"correctAnswer":"artikulieren"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: Prejudices remain implicit if they are not explicitly reflected upon","wordBankItems":["Vorurteile","bleiben","implizit",",","wenn","sie","nicht","explizit","reflektiert","werden","."],"correctAnswer":"Vorurteile bleiben implizit , wenn sie nicht explizit reflektiert werden ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"''Die Zugänglichkeit'' means?","options":["accessibility","approachability","comprehensibility","readability"],"correctAnswer":"accessibility"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('aa000000-0000-0000-0000-0000000002d8',1,'APPROVED','PUBLISHED',
'{"objectives":["Discuss translation and interpreting at B2","Use Übersetzung und Dolmetschen vocabulary","Talk about translation theory, cultural mediation, and professional interpreting"],"explanation":{"intro":"Translation and interpreting vocabulary covers translation theory, the cultural dimension of translation, and professional language mediation at B2.","culturalNote":"Übersetzung und Dolmetschen: Key distinction: Übersetzen (translation — written) vs. Dolmetschen (interpreting — oral: Simultandolmetschen = simultaneous, Konsekutivdolmetschen = consecutive). Key concept: Equivalence (formal vs. dynamic — Eugene Nida). Lawrence Venuti: Domestication (invisible translator — reader-friendly) vs. Foreignisation (visible translator — preserves strangeness). Walter Benjamin (''Die Aufgabe des Übersetzers'' — ''The Task of the Translator'' — 1923 — translation reveals the ''pure language'' hidden in both). Germany: major translation nation — Übersetzungspreis (translation prize). Key challenge: untranslatable words — Schadenfreude (malicious joy), Weltschmerz (world pain), Sehnsucht (longing/yearning). Frankfurter Buchmesse (Frankfurt Book Fair — largest book fair — translation rights sold)."},"examples":[{"german":"Übersetzung ist kein bloßes Codewechseln, sondern kulturelle Vermittlung: Jede Übersetzung trifft Entscheidungen über das Maß an Domestizierung und Verfremdung — wie viel vom Fremden sie dem Leser vermitteln und wie viel sie anpassen soll. Diese Entscheidungen sind keine rein ästhetischen, sondern ethische: Sie bestimmen, inwieweit das Andere als fremd wahrnehmbar bleibt.","english":"Translation is not mere code-switching, but cultural mediation: every translation makes decisions about the degree of domestication and foreignisation — how much of the foreign it conveys to the reader and how much it should adapt. These decisions are not purely aesthetic, but ethical: they determine to what extent the Other remains perceivable as foreign."},{"german":"Das Simultan-Dolmetschen ist eine kognitive Hochleistung: Der Dolmetscher verarbeitet gleichzeitig eingehende Sprache, sucht nach äquivalenten Ausdrücken in der Zielsprache und produziert kontinuierlich gesprochene Ausgabe — eine Dreifachbelastung, die professionelle Ausbildung, konzentrierte Arbeitsphasen und regelmäßige Pausen erfordert.","english":"Simultaneous interpreting is a high cognitive performance: the interpreter simultaneously processes incoming language, searches for equivalent expressions in the target language, and continuously produces spoken output — a triple load that requires professional training, concentrated work phases, and regular breaks."}],"rewards":{"xp":150,"coins":80},"metadata":{"estimatedMinutes":20,"canDo":"I can discuss domestication vs. foreignisation, Benjamin on translation, and simultaneous interpreting at B2."}}',
'{"items":[{"word":"die Vermittlung","translation":"mediation","pronunciation":"dee fer-MIT-loong","example":"Kulturelle Vermittlung."},{"word":"die Domestizierung","translation":"domestication","pronunciation":"dee do-mes-ti-ZEE-roong","example":"Domestizierung vs. Verfremdung."},{"word":"die Verfremdung","translation":"foreignisation/defamiliarisation","pronunciation":"dee fer-FREM-doong","example":"Verfremdung in Übersetzung."},{"word":"inwieweit","translation":"to what extent","pronunciation":"in-VEE-vyte","example":"Inwieweit fremd bleiben."},{"word":"äquivalent","translation":"equivalent","pronunciation":"ä-kvi-vah-LENT","example":"Äquivalenter Ausdruck."},{"word":"die Dreifachbelastung","translation":"triple load","pronunciation":"dee DRY-fakh-beh-las-toong","example":"Kognitive Dreifachbelastung."}]}',
'{"title":"Diese Entscheidungen sind nicht X, sondern Y — these decisions are not X but Y (ethical stakes of apparently technical choices)","pattern":"diese Entscheidungen sind nicht rein X, sondern Y = these decisions are not purely X, but Y (nicht rein = not purely — concedes partial applicability; sondern = but rather — corrects; elevates the stakes from technical to moral/political)","explanation":"Nicht rein X, sondern Y = not purely X, but Y (rein = purely — concedes X is partly there, but insufficient description). Diese Entscheidungen sind keine rein ästhetischen, sondern ethische = These decisions are not purely aesthetic, but ethical. The pattern raises the stakes: what might seem like a merely technical or stylistic decision (X) is actually ethical/political (Y). Common in critical theory, applied ethics, and political discourse. Compare: nicht neutral, sondern politisch (not neutral, but political), nicht bloß X, sondern Y (not merely X, but Y — ''bloß'' softens X even more), nicht nur X, sondern auch Y (not only X, but also Y — additive rather than replacement).","examples":[{"sentence":"Diese Auswahl ist keine rein technische, sondern eine politische Entscheidung.","translation":"This selection is not a purely technical, but a political decision."},{"sentence":"Architektur ist keine rein ästhetische, sondern eine soziale Praxis.","translation":"Architecture is not a purely aesthetic, but a social practice."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"''Die Verfremdung'' means?","options":["foreignisation/defamiliarisation","alienation","strangeness","distancing"],"correctAnswer":"foreignisation/defamiliarisation"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"Translation is not mere code-switching, but cultural mediation: every translation makes decisions about the degree of domestication and foreignisation — how much of the foreign it conveys to the reader and how much it should adapt. These decisions are not purely aesthetic, but ethical: they determine to what extent the Other remains perceivable as foreign.","options":["Übersetzung ist kein bloßes Codewechseln, sondern kulturelle Vermittlung: Jede Übersetzung trifft Entscheidungen über das Maß an Domestizierung und Verfremdung — wie viel vom Fremden sie dem Leser vermitteln und wie viel sie anpassen soll. Diese Entscheidungen sind keine rein ästhetischen, sondern ethische: Sie bestimmen, inwieweit das Andere als fremd wahrnehmbar bleibt.","Übersetzen bedeutet mehr als Wörter auszutauschen — es ist kulturelle Vermittlung.","Jede Übersetzung muss zwischen Nähe zur Ausgangssprache und Lesbarkeit abwägen.","Übersetzungsentscheidungen haben ethische Konsequenzen."],"correctAnswer":"Übersetzung ist kein bloßes Codewechseln, sondern kulturelle Vermittlung: Jede Übersetzung trifft Entscheidungen über das Maß an Domestizierung und Verfremdung — wie viel vom Fremden sie dem Leser vermitteln und wie viel sie anpassen soll. Diese Entscheidungen sind keine rein ästhetischen, sondern ethische: Sie bestimmen, inwieweit das Andere als fremd wahrnehmbar bleibt."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Diese Auswahl ist keine rein technische, sondern eine ___ Entscheidung.","options":["politische","ethische","soziale","normative"],"correctAnswer":"politische"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: Architecture is not a purely aesthetic but a social practice","wordBankItems":["Architektur","ist","keine","rein","ästhetische",",","sondern","eine","soziale","Praxis","."],"correctAnswer":"Architektur ist keine rein ästhetische , sondern eine soziale Praxis ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"''Inwieweit'' means?","options":["to what extent","how far","in what way","as far as"],"correctAnswer":"to what extent"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('aa000000-0000-0000-0000-0000000002d9',1,'APPROVED','PUBLISHED',
'{"objectives":["Discuss language decay and cultivation at B2","Use Sprachverfall und Sprachpflege vocabulary","Talk about debates about language decay, language purism, and prescriptivism vs. descriptivism"],"explanation":{"intro":"Language decay and cultivation vocabulary covers German language purism, descriptivism vs. prescriptivism, and the politics of Sprachpflege at B2.","culturalNote":"Sprachverfall und Sprachpflege: Key debate: Sprachverfall (language decay — alarmist claim that German is degenerating). Classic complaints: Anglizismen (anglicisms), Jugendsprache (youth language — ''Digga'', ''cringe'', ''läuft bei dir''), shortening in texting (SMS-Sprache), grammatical errors. Key institutions: Verein Deutsche Sprache (VDS — ''language protection'' — prescriptivist — monthly ''Sprachpfuscherei'' award). Duden (descriptive AND prescriptive — used as authority). Sprachwissenschaft vs. Sprachpflege: linguists generally descriptive (language change = natural), prescriptivists normative. Unwort des Jahres (Un-word of the Year — since 1991 — linguistically or ethically objectionable words). Key concept: Sprachlicher Wandel (language change — always happened — Middle High German vs. Modern German). Key argument: ''The language that people use IS the language.''"},"examples":[{"german":"Klagen über Sprachverfall sind so alt wie die Schriftlichkeit selbst: Jede Generation hat die sprachlichen Innovationen der nächsten als Zeichen des Verfalls gedeutet — was heute als schlechtes Deutsch gilt, war gestern eine frische Neubildung. Linguistisch beschreibt Sprachwandel keine Degradation, sondern Anpassung an veränderte kommunikative Bedürfnisse.","english":"Laments about language decay are as old as writing itself: every generation has interpreted the linguistic innovations of the next as signs of decay — what is regarded as bad German today was a fresh new formation yesterday. Linguistically, language change describes not degradation, but adaptation to changed communicative needs."},{"german":"Der Konflikt zwischen Sprachbeschreibung und Sprachnormierung ist ein Konflikt über Autorität: Wer entscheidet, was ''richtiges'' Deutsch ist — der Sprachgebrauch der Gemeinschaft oder eine Institution mit normativer Deutungshoheit? Die Linguistik antwortet descriptiv: Sprache ist, was Sprecher tun; die Sprachpflege antwortet normativ: Sprache ist, was Sprecher tun sollten.","english":"The conflict between language description and language regulation is a conflict over authority: who decides what ''correct'' German is — the usage of the community or an institution with normative interpretive authority? Linguistics answers descriptively: language is what speakers do; language cultivation answers normatively: language is what speakers should do."}],"rewards":{"xp":150,"coins":80},"metadata":{"estimatedMinutes":20,"canDo":"I can discuss prescriptivism vs. descriptivism, language change as natural process, and Sprachpflege at B2."}}',
'{"items":[{"word":"die Klage","translation":"lament/complaint","pronunciation":"dee KLAH-geh","example":"Klagen über Verfall."},{"word":"die Neubildung","translation":"new formation","pronunciation":"dee NOY-bil-doong","example":"Sprachliche Neubildung."},{"word":"die Degradation","translation":"degradation","pronunciation":"dee deh-grah-dah-TSYOHN","example":"Degradation der Sprache."},{"word":"deskriptiv","translation":"descriptive","pronunciation":"des-krip-TEEF","example":"Deskriptive Linguistik."},{"word":"normativ","translation":"normative","pronunciation":"nor-mah-TEEF","example":"Normative Sprachpflege."},{"word":"die Deutungshoheit","translation":"interpretive authority","pronunciation":"dee DOY-toonks-ho-hyt","example":"Normative Deutungshoheit."}]}',
'{"title":"Linguistik antwortet deskriptiv: X ist, was Y tut; Sprachpflege antwortet normativ: X ist, was Y tun sollte","pattern":"X antwortet deskriptiv: Y ist, was Z tut; X antwortet normativ: Y ist, was Z tun sollte = X answers descriptively: Y is what Z does; X answers normatively: Y is what Z should do (deskriptiv vs. normativ — parallel contrast; ist vs. sollte = is vs. should be)","explanation":"Deskriptiv (descriptive — describes how things are) vs. normativ (normative — prescribes how things should be). Die Linguistik antwortet deskriptiv: Sprache ist, was Sprecher tun = Linguistics answers descriptively: language is what speakers do. Die Sprachpflege antwortet normativ: Sprache ist, was Sprecher tun sollten = Language cultivation answers normatively: language is what speakers should do. The pattern cleanly opposes descriptive and prescriptive approaches using parallel structure. Indikativ (ist) = descriptive; Konjunktiv II/Modalverb (sollte) = normative. This is a very transferable pattern for any is/ought distinction.","examples":[{"sentence":"Soziologie beschreibt deskriptiv: Gesellschaft ist, wie Menschen leben; Ethik fragt normativ: wie Menschen leben sollten.","translation":"Sociology describes descriptively: society is how people live; ethics asks normatively: how people should live."},{"sentence":"Die Wissenschaft antwortet deskriptiv: Klimawandel ist real; die Politik antwortet normativ: Emissionen sollten sinken.","translation":"Science answers descriptively: climate change is real; politics answers normatively: emissions should fall."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"''Die Klage'' means?","options":["lament/complaint","grievance","accusation","claim"],"correctAnswer":"lament/complaint"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"Laments about language decay are as old as writing itself: every generation has interpreted the linguistic innovations of the next as signs of decay — what is regarded as bad German today was a fresh new formation yesterday. Linguistically, language change describes not degradation, but adaptation to changed communicative needs.","options":["Klagen über Sprachverfall sind so alt wie die Schriftlichkeit selbst: Jede Generation hat die sprachlichen Innovationen der nächsten als Zeichen des Verfalls gedeutet — was heute als schlechtes Deutsch gilt, war gestern eine frische Neubildung. Linguistisch beschreibt Sprachwandel keine Degradation, sondern Anpassung an veränderte kommunikative Bedürfnisse.","Sprachverfall ist ein Mythos — Sprache verändert sich immer schon.","Jede Generation denkt, die nächste spricht schlechter.","Sprachwandel ist Anpassung, kein Verfall."],"correctAnswer":"Klagen über Sprachverfall sind so alt wie die Schriftlichkeit selbst: Jede Generation hat die sprachlichen Innovationen der nächsten als Zeichen des Verfalls gedeutet — was heute als schlechtes Deutsch gilt, war gestern eine frische Neubildung. Linguistisch beschreibt Sprachwandel keine Degradation, sondern Anpassung an veränderte kommunikative Bedürfnisse."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Die Linguistik antwortet deskriptiv: Sprache ist, was Sprecher ___; die Sprachpflege antwortet normativ: Sprache ist, was Sprecher tun ___.","options":["tun / sollten","machen / sollen","sagen / müssen","benutzen / dürfen"],"correctAnswer":"tun / sollten"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: Science answers descriptively climate change is real","wordBankItems":["Die","Wissenschaft","antwortet","deskriptiv",":","Klimawandel","ist","real","."],"correctAnswer":"Die Wissenschaft antwortet deskriptiv : Klimawandel ist real ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"''Die Deutungshoheit'' means?","options":["interpretive authority","definitional sovereignty","meaning control","interpretive power"],"correctAnswer":"interpretive authority"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('aa000000-0000-0000-0000-0000000002da',1,'APPROVED','PUBLISHED',
'{"objectives":["Discuss global English and linguistic diversity at B2","Use Globales Englisch und Sprachvielfalt vocabulary","Talk about English as a lingua franca, language endangerment, and Europe''s language policy"],"explanation":{"intro":"Global English and linguistic diversity vocabulary covers English as a lingua franca, endangered languages, and Europe''s multilingual language policy at B2.","culturalNote":"Globales Englisch und Sprachvielfalt: English as Lingua Franca (ELF): ~400m native speakers, ~1.5bn users total — science, business, diplomacy. Key concern: English academic hegemony — German scientists publish in English, reducing German scientific vocabulary. Crystal (''Language Death'' 2000 — every 2 weeks one language dies — 7000 languages today — ~3000 endangered). Language diversity as biodiversity analogy. Key institution: Europäische Kommission (Mehrsprachigkeitspolitik — EU has 24 official languages — costly but principled). UNESCO Atlas of World Languages in Danger. Key concept: Linguistic imperialism (Phillipson). Language revitalisation: Welsh (Cymraeg), Irish (Gaeilge), Breton. In Germany: Niederdeutsch (Low German — protected — Europäische Charta der Regional- oder Minderheitensprachen). Sorbian language (Lusatia — protected in Saxony/Brandenburg)."},"examples":[{"german":"Die Dominanz des Englischen als Lingua Franca ist ein zweischneidiges Schwert: Sie erleichtert internationale wissenschaftliche Kommunikation und senkt Übersetzungskosten, aber sie privilegiert systematisch Muttersprachler, diskriminiert Nicht-Muttersprachler und führt zu einer schleichenden Verarmung wissenschaftlicher Sprachdiversität — Konzepte, die sich in einer Sprache nicht ausdrücken lassen, verschwinden aus dem Diskurs.","english":"The dominance of English as a lingua franca is a double-edged sword: it facilitates international scientific communication and lowers translation costs, but it systematically privileges native speakers, discriminates against non-native speakers, and leads to a creeping impoverishment of scientific linguistic diversity — concepts that cannot be expressed in one language disappear from discourse."},{"german":"Sprachentod ist kein unvermeidliches Naturphänomen, sondern Ergebnis politischer Entscheidungen: Minderheitensprachen sterben, wenn Staaten Schulen schließen, Kinder zur Assimilation zwingen und sozialer Aufstieg nur über die Mehrheitssprache erreichbar ist — Sprachenvielfalt zu erhalten erfordert aktive Sprachenpolitik, nicht nostalgische Sprachpflege.","english":"Language death is not an unavoidable natural phenomenon, but the result of political decisions: minority languages die when states close schools, force children into assimilation, and social mobility is only achievable through the majority language — preserving linguistic diversity requires active language policy, not nostalgic language cultivation."}],"rewards":{"xp":150,"coins":80},"metadata":{"estimatedMinutes":20,"canDo":"I can discuss English as lingua franca, language death, and EU multilingualism at B2."}}',
'{"items":[{"word":"zweischneidig","translation":"double-edged","pronunciation":"TSVY-shny-dikh","example":"Zweischneidiges Schwert."},{"word":"schleichend","translation":"creeping/insidious","pronunciation":"SHLY-khend","example":"Schleichende Verarmung."},{"word":"die Verarmung","translation":"impoverishment","pronunciation":"dee fer-ARM-oong","example":"Sprachliche Verarmung."},{"word":"unvermeidlich","translation":"unavoidable","pronunciation":"oon-fer-MY-dlikh","example":"Kein unvermeidliches Phänomen."},{"word":"zwingen zu","translation":"to force into","pronunciation":"TSVENG-en tsoo","example":"Zur Assimilation zwingen."},{"word":"die Minderheitensprache","translation":"minority language","pronunciation":"dee min-der-HY-ten-shprah-kheh","example":"Minderheitensprachen schützen."}]}',
'{"title":"X ist kein unvermeidliches Y, sondern Ergebnis politischer Z — X is not an unavoidable Y but the result of political Z","pattern":"X ist kein unvermeidliches Y, sondern Ergebnis politischer Z = X is not an unavoidable Y, but the result of political Z (kein unvermeidliches Y = not an unavoidable Y — denies inevitability; sondern Ergebnis politischer Z = but the result of political Z — politicises what seemed natural)","explanation":"Kein unvermeidliches Y = not an unavoidable Y (denies inevitability — unvermeidlich = unavoidable). Sondern Ergebnis politischer Z = but the result of political Z (politicises the outcome — it''s not fate, but the product of political decisions). Sprachentod ist kein unvermeidliches Naturphänomen, sondern Ergebnis politischer Entscheidungen = Language death is not an unavoidable natural phenomenon, but the result of political decisions. This pattern is widely used to denaturalise and politicise: what seems natural/inevitable is revealed as contingent/political. Compare: nicht schicksalhaft, sondern gemacht (not fated, but made), nicht gegeben, sondern konstruiert (not given, but constructed), historisch kontingent (historically contingent — more technical), vermeidbar durch... (avoidable through... — positive framing).","examples":[{"sentence":"Armut ist kein unvermeidliches Schicksal, sondern Ergebnis politischer Strukturen.","translation":"Poverty is not an unavoidable fate, but the result of political structures."},{"sentence":"Krieg ist kein unvermeidliches Naturereignis, sondern Ergebnis politischer Entscheidungen.","translation":"War is not an unavoidable natural event, but the result of political decisions."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"''Schleichend'' means?","options":["creeping/insidious","gradual","slow","covert"],"correctAnswer":"creeping/insidious"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"Language death is not an unavoidable natural phenomenon, but the result of political decisions: minority languages die when states close schools, force children into assimilation, and social mobility is only achievable through the majority language — preserving linguistic diversity requires active language policy, not nostalgic language cultivation.","options":["Sprachentod ist kein unvermeidliches Naturphänomen, sondern Ergebnis politischer Entscheidungen: Minderheitensprachen sterben, wenn Staaten Schulen schließen, Kinder zur Assimilation zwingen und sozialer Aufstieg nur über die Mehrheitssprache erreichbar ist — Sprachenvielfalt zu erhalten erfordert aktive Sprachenpolitik, nicht nostalgische Sprachpflege.","Sprachen sterben aus, weil Staaten Minderheiten zwingen, die Mehrheitssprache zu lernen.","Sprachentod ist politisch verursacht, nicht unvermeidlich.","Sprachen zu erhalten erfordert aktive Politik, nicht nur guten Willen."],"correctAnswer":"Sprachentod ist kein unvermeidliches Naturphänomen, sondern Ergebnis politischer Entscheidungen: Minderheitensprachen sterben, wenn Staaten Schulen schließen, Kinder zur Assimilation zwingen und sozialer Aufstieg nur über die Mehrheitssprache erreichbar ist — Sprachenvielfalt zu erhalten erfordert aktive Sprachenpolitik, nicht nostalgische Sprachpflege."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Armut ist kein unvermeidliches Schicksal, sondern Ergebnis politischer ___.","options":["Strukturen","Entscheidungen","Verhältnisse","Bedingungen"],"correctAnswer":"Strukturen"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: War is not an unavoidable natural event but the result of political decisions","wordBankItems":["Krieg","ist","kein","unvermeidliches","Naturereignis",",","sondern","Ergebnis","politischer","Entscheidungen","."],"correctAnswer":"Krieg ist kein unvermeidliches Naturereignis , sondern Ergebnis politischer Entscheidungen ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"''Unvermeidlich'' means?","options":["unavoidable","inevitable","inescapable","inexorable"],"correctAnswer":"unavoidable"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

